private boolean matchesModifier(String[] modifierTokens, ArrayList<char[]> searchTokens, int begin) {
    int j = 0;
    while ((begin + j) < searchTokens.size() && j < modifierTokens.length) {
      String token = new String(searchTokens.get(begin + j));
      if (!token.toLowerCase().equals(modifierTokens[j].toLowerCase())) return false;
      if (++j == modifierTokens.length) return true;
    }
    return false;
}

